import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集說卷十四","description":"周易集說 - 周易集說卷十四","frontmatter":{"title":"周易集說卷十四","description":"周易集說 - 周易集說卷十四"},"headers":[],"relativePath":"classics/jishuo/015.md","filePath":"classics/jishuo/015.md"}'),r={name:"classics/jishuo/015.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集說卷十四" tabindex="-1">周易集說卷十四 <a class="header-anchor" href="#周易集說卷十四" aria-label="Permalink to “周易集說卷十四”">​</a></h1><p>欽定四庫全書</p><p>宋俞琰撰</p><p>文王之辭謂之經，孔子之辭謂之傳。傳者所以釋經之辭也。經有彖辭，即文王所繫於卦下之辭。孔子釋文王卦下之辭而傳述其意，故謂之彖傳。古者經與傳各為一書，自費直以傳解經，而後鄭玄以彖傳連經文，然猶若今乾卦次序。至王弼乃自坤卦而始每卦以彖傳移綴於彖辭之後，又加以「彖曰」兩字冠之，後之人遂不謂之彖傳，而直謂之彖。夫以孔子之彖傳為彖，則文王之彖辭當復謂之何哉？魏晉而下，去古日遠，訛以傳訛，至今讀者習以為常，弗察也。先儒謂西漢時六經與傳皆別行，逮東漢諸儒作注，始合經傳為一。如春秋三傳之文，不與經連，故石經公羊傳皆無經文，藝文志所載毛詩故訓傳亦與經別。及馬融為周禮注，乃雲欲省學者兩讀，故具載本文，而就經為注。鄭玄與馬融同時，玄以易傳連於易經，蓋仿融例，而弼又援玄例也。乃若杜預分左氏傳連於經，範望散太玄測於八十一首之下，皆欲取便於學者之誦覽故也。唐太宗詔名儒定九經正義，孔穎達奉詔與諸儒參議，於易則獨取王弼。自唐至宋，著為定論，不本正義者以為異說。於是後之學者，惟王弼是從，竟莫敢移動。呂汲公、王原叔、晁以道、李巽巖、呂東萊、朱紫陽皆以分經合傳非古。吳仁杰、稅與權編周易古經，亦皆極論王弼之失。讀易者要當審其是，不可狃於舊說，而復以彖傳為彖雲。</p><p>「大哉乾元，萬物資始，乃統天。」</p><p>紫陽朱子曰：「此專以天道明乾義。」又曰：「此一節首釋元義。」愚謂彖辭雲「元亨利貞」，不過謂大亨而利於正。彖傳分而為四，又以「元」為重，故特贊之曰：「大哉乾元。」物有氣，斯有形。始者氣之元，生者形之元。形雖資坤而生，氣則資乾而始，故曰「萬物資始」。夫乾之「元亨利貞」，析之以配四時，固皆天之德。若獨論「乾元」之大，則「元」者生意也，「亨」者生意之長，「利」者生意之遂，「貞」者生意之成。「亨利貞」之三者，皆屬「元」之所統，故曰「乃統天」。「統」者，以一該眾，無所不總之謂。大莫大於天，而元統之，則天亦萬物中之物耳。元其大矣哉！</p><p>「雲行雨施，品物流形。」紫陽朱子曰：「此釋乾之亨也。」愚謂乾之「亨」，乃陽氣亨通而物皆暢達之時。是時天油然作雲，沛然下雨，凡昔之凝滯者，皆至此而流動；昔之潛伏者，皆至此而形見。故曰：</p><p>「雲行雨施，品物流形。」施，去聲，始豉反。前言萬物，此言「品物」，萬與品同歟？異歟？曰：元為稟氣之始，未可區別，故總謂之萬。亨則流動形見，而洪纖高下各有區別，故特謂之「品」。或謂孔子贊乾四德，獨不言「亨」，何也？誠齋楊氏曰：言元、言利、言貞，而不言亨，非不言亨也，</p><p>雲行雨施，品物流形，即亨也。節齋蔡氏曰：「雲行雨施，亨之見乎氣也；品物流形，亨之見乎形也。」</p><p>大明終始，六位時成，時乘六龍以御天。</p><p>「終」，謂下乾之終，九三是也。「始」，謂上乾之始，九四是也。九三、九四乃乾下乾上之交接處，一乾方終，一乾又始，則生意於此，續而不絕，故不曰始終，而特曰「終始」。說卦雲「終萬物，始萬物」，亦是此意。彼言艮東北醜寅之交，此則言兩乾上下之交也。或以初為始，上為終，初上乃一卦之始終，非此之謂也。或以元為始，貞為終，「元貞」乃四德之始終，非此之謂也。「大明終始」，謂聖人大明天道之終始，以示人也。「六位」，卦之六畫也。易六畫而成卦，一畫有一畫之位，一位有一位之時。乾六位各以時成，則乾道於是乎備矣。乾而止於三畫，則終而無繼，豈生生之謂易哉？所謂「大明終始」，所謂「六位時成」，皆發明重乾六畫之義。六龍，乾之六爻也。六位，言六畫之定分；六龍，言六爻之變象。六位乃諸卦之所同，六龍則純乾之所獨也。時乘六龍以御天，謂聖人當此之時，乘六陽之亨通以行天道，與天道同一亨通也。</p><p>紫陽朱子曰：「此言聖人之元亨也。」</p><p>乾道變化，各正性命，保合大和，乃利貞。</p><p>紫陽朱子曰：「此言乾道變化，無所不利，而萬物各得其性命以自全，以釋利貞之義也。」愚謂：乾道，天之道也。變化，陰陽之變化也。陰變為陽，陽化為陰，寒暑之往來是也。寒往則暑來，暑往則寒來，一往一來而不已，是之謂道。天道之所以為變化者何？變化萬物也。萬物蓋隨四時之推移，而為之變，為之化也。天所賦為命，物所受為性。物受天之所賦，自形自色，自生自長，莫不小遂其小，大遂其大，是為各正性命，謂各得其性命之正也。大，音泰。大和，即元氣也。保謂保全而無虧，合謂合聚而不散。物皆斂華就實，而保合大和，則又為來春發生之地也。乃利貞者，由是而利貞也。承上文之意，推本元亨而言也。蓋自元而亨，亨而利，利而貞，貞則又元，不貞則無以為元。「元」乃物之萌芽初出時，「亨」乃物之長茂時，「利」乃物之收斂時，「貞」乃物之結實而歸宿處。唯有此歸宿處，是以貞下起元，靜極而復動，冬極而復春，生意常周流而不絕。若使元亨而不利貞，春夏而不秋冬，則元氣磔裂，發散無餘，而乾道或幾乎熄矣，何變化之有？</p><p>首出庶物，萬國咸寧。</p><p>紫陽朱子曰：「此言聖人之利貞也。」愚謂：聖人聰明睿知，冠乎群倫，超出庶物，足以有臨，足以表正萬邦，而天下皆得其所安，故曰</p><p>「首出庶物，萬國咸寧」。「首」即「元」也。萬國願戴聖人為首，亦猶萬物資始於乾之「元」也。孔子贊乾之「利貞」，而又言「首」，其意亦可見矣。蓋曰「貞」不終於「貞」，而「貞」之後又繼以「元」也。聖人體乾之「元」，出而君臨萬國，是為萬國之元首。萬國各有其君，則又各為其國之首。蓋推廣乾元之大，以見生生之道無窮也。乾彖傳三言物，初言「萬物」，次言「品物」，又言「庶物」，何其異耶？曰：萬物，偕天而言也，品物，以在地而言也。庶物即品物，對人君而言，則謂之庶。庶者，眾也。</p><p>至哉坤元，萬物資生，乃順承天。</p><p>乾，天道也。坤，地道也。天尊地卑，故乾元稱「大」，「坤元」稱「至」。「至」義差緩，雖不若「大」之盛，然乾之所至，坤亦「至」焉。坤元蓋與「乾元」同其大也。孔子嫌於兩大同稱，故變文而贊「坤」之「元」曰「至哉」，所以尊「乾」也。聖人於尊卑之辨，謹嚴如此。萬物資「乾元」以始，有氣而未有形；資「坤元」以生，乃有形，父母之道也。是故天氣不下降於地，則地亦不能生物。地之生物，乃順而承天之施也。「承」，受也，奉也。「坤」順「乾」而受乾之施，下奉上之道也。</p><p>坤厚載物，德合無疆，含弘光大，品物咸亨。</p><p>「順」與「厚」，皆「坤」德。順而承天之施，所以生物；厚而合天之無疆，所以載物。「乾」德之大，無不復幬，而無此疆爾界之限；「坤」德之厚，無不持載，亦無此疆爾界之限，是之謂合夫「坤」。「其靜也翕」，翕則含弘；「其動也闢」，闢則光大。含弘如此，光大如此，是以品物鹹得亨通也。或曰：陽明而陰暗，陽大而陰小，光大者乾之德，「坤」安得光大？曰：「坤」之德含容弘博，而與乾合，則亦光明盛大也。孔子贊「坤」之德，不曰「大」而曰「至」，蓋以尊無二上，而不可與「乾」並稱。次贊「坤」之「亨」，乃曰「含弘光大」，則「坤」德之大，實與「乾」同。不然，「坤」何以為「乾」之配？</p><p>牝馬地類，行地無疆。柔順利貞，君子攸行。</p><p>龍行天之物，故以象天。馬行地之物，故以象地。坤順而承天，是以博厚載物，而合乾無疆。牝馬柔順而類地，是以引重致遠，而行地無疆。彖辭雲：「利牝馬之貞」，孔子加以「柔順」二字，而釋之曰：「柔順利貞」，何也？彖辭雲「君子有攸往」，自連下文，孔子並及之，而釋之曰「君子攸行」，又何也？曰：孔子所以錯綜其辭者，蓋又發明文王言外之意，而謂君子所行柔順而貞則宜，柔順而不貞則不宜也。孝經雲：故當不義，則子不可以不爭於父，臣不可以不爭於君。故當不義則爭之，從父之令，又焉得為孝乎？坤，臣子之道也。臣子之事君父，唱則必應，固不可不柔順。然倡之不以道，而亦應焉，則過於柔順而不貞矣。過於柔順而不貞，則柔為小人之善柔，順為小人之阿順，豈君子之所宜哉！</p><p>先迷失道，後順得常。西南得朋，乃與類行；東北喪朋，乃終有慶。安貞之吉，應地無疆。</p><p>坤不能自行，順乾之健而行。君子有攸往，先則迷而失其道，後則順而得其常。西南兌、離、巽皆坤朋，乃與類行。東北雖喪其朋，然陰當從陽，乃終有得主之慶。慶，叶韻平聲，音羌。君子之出處，隨地而安，隨地而貞，不限西南東北皆吉，故曰：安貞之吉，應地無疆。方其在西南，則安於西南，猶女子在室，則安於父母家。及其往東北，則安於東北，猶女子嫁而從夫，則安於夫家。在此亦貞而吉，在彼亦貞而吉，君子無入而不自得焉。或者乃謂惟當貞於陽方，不當貞於陰方，則拘於一，而與「應地無疆」之義背馳矣。坤彖傳凡三言「順」，三言「無疆」。「順」，坤德，「無疆」則乾德也。坤合乾之「無疆」，則地亦無疆。是故馬之無疆類地，君子之無疆應地。</p><p>屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。</p><p>易六十四卦，惟乾、坤二卦純剛純柔，無所謂上下之乘承，亦無所謂內外之配應。其餘六十二卦，則皆剛柔錯雜，乃有乘承配應。既有乘承配應，則其說千變萬化而無窮矣。</p><p>「剛」，謂乾之九，「柔」，謂坤之六。「始交」，謂乾之初交坤而成震。「難生」，謂坎水之險在前。此合上下二體，釋卦之名義也。「動」者，震之德。「險」者，坎之德。震在坎中，是謂「動乎險中」。此雖具上下卦二體之德，並言其意則在初九。初九蓋屯之主爻也。「大」，釋「元」字。「大亨貞」，謂屯之時，動則可以出險而大亨。固不容不動，然又不可遽動，唯以貞道固守則利也。陽在陰中，則激而為雷。陰陽和洽，則烝而為雨。「雷雨之動滿盈」，謂震雷坎雨，閉固鬱塞，必至於滿盈而後動，以象屯道艱難，而未能遽通也。「天造」，時運也。「草」，震象，謂雜亂而未定也。「昧」，坎象，謂幽暗而未明也。屯之時如此，豈宜有所往？唯宜「建侯」，「建侯」所以濟難也。「不寧」，不遑寧處也。難生故「不寧」。侯未建則難未解，欲寧處得乎？</p><p>山下有險，險而止，「蒙」。「蒙亨」，以亨行時中也。「匪我求童蒙，童蒙求我」，志應也。「初筮告」，以剛中也。「再三瀆，瀆則不告」，瀆蒙也。蒙以養正，聖功也。</p><p>蒙卦，下坎水，上艮山，退則困於坎水之險，而不可處；進則閡於艮山之止，而不可往。進退莫知所之，是之謂「蒙」。「山下有險」，言卦象。「險而止」，言卦德。「蒙」，言卦名。自此以下，皆言卦義。「以亨行」者，蒙以亨而後行，未亨則止，既亨則行也。「蒙」豈能遽亨？所以「亨」者，時也。當其可之謂「時」，蓋「不憤則不啟，不悱則不發」也。「時中」者，於其可亨之時而亨之，不先時、不後時也。「志」，謂五之志，「應」，謂應二也。二以剛明之賢處下，五以「童蒙」之君居上，非是二求五，蓋五之志應於二也。伊川程子曰：「賢者在下，豈可自進以求於君？」苟自求之，必無信用之理。古之人所以必待人君致敬盡禮而後往者，非欲自為尊大，蓋其尊德樂道，不如是不足與有為也。剛中，指九二。以其剛而得中，則告而有節，乃可決人之疑也。瀆蒙，謂告之不一，則其說煩亂，而愈滋其惑也。是不惟問者瀆，告者亦瀆也。夫童蒙求我之初，其志蓋專一也，吾當盡誠以告之，不告則失人，至於再，至於三，則煩數而其志不專一矣。不若不告，告則失言也。聖者，無所不通之謂。童蒙之時，便當以正道涵養其正性，是乃作聖之功也。古之人含德之厚，比於赤子。大人之所以為大人者，不失其赤子之心而已。童蒙之時，情竇未開，天真未散，粹然一齣於正，所謂赤子之心是也。蓋涵養正性，全在童蒙之時。若童蒙之時，無所養而失其正，則他日慾望其作聖，不可得矣。文王曰：「初筮告。」孔子釋之曰：「以剛中也。」文王曰：「再三瀆，瀆則不告。」孔子釋之曰：「瀆蒙也。」文王曰：「利貞。」孔子釋之曰：「蒙以養正，聖功也。」孔子蓋發明文王言外之意，故其意又加詳焉。或曰：「亨行」二字羨文。</p><p>需，須也。險在前也。剛健而不陷，其義不困窮矣。「需，有孚，光亨貞吉」，位乎天位，以正中也。「利涉大川」，往有功也。「須」，待也。「險在前」，謂前遇坎水之險也。「剛健而不陷」，謂乾不陷於坎也。坎雖險，乾以剛健能需而不躁進，則無陷溺之憂矣。揆之以義，蓋不至於困窮也。卦互兌，兌為澤，坎水在兌澤之上，則澤有水，而其象亦為不困窮也。「位乎天位」，謂以九居五也。上五兩爻皆屬天位，而五為天之正位，故言「天位」。「正中」，謂正得其中也。需之時，剛明之君，與剛明之臣，同德相孚，五也。又能以正道固守，而其剛明之德，不為二陰所揜，是以亨且「吉」也。正中以明，「有孚」與貞。位乎天位，以明，「光亨」與吉。「往有功」，謂需極則當往，往則有難濟之功。蓋無不往，而坐待險平之理也。此卦彖傳先以卦德釋卦名義，而曰：</p><p>「需，須也，險在前也，剛健而不陷，其義不困窮矣。」蓋合二體而言。次曰：「需，有孚，光亨，貞吉，位乎天位，以正中也」。蓋贊九五之主爻。終曰「利涉大川，往有功也」。蓋又合二體之德言。或曰，「需」之為卦，以「乾」遇坎而為之辭。故「乾」雖剛健，而以險難在前，不能不為之需。乃若遇「巽」，則其剛健為陰小所畜。遇艮，則其剛健為陽大所畜。各因其所遇而為之辭也。同是「坎」也，以「震」遇之，則動乎險中，而能濟難，屯卦是也。以「艮」遇之，則見險而能止，不犯於難，蹇卦是也。「需」則知險難在前，遂不躁進，又有剛健濟難之才，遂不即止，必有待焉而後進，與屯蹇異矣。</p><p>「訟」，上剛下險，險而健，訟。訟「有孚，窒惕，中吉」，剛來而得中也。「終兇」，訟不可成也。「利見大人」，尚中正也。「不利涉大川」，入於淵也。</p><p>上剛指「乾」。下險指「坎」。在上者，恃其剛以陵下。在下者，懷其險以伺上。一剛一險，「訟」之由也。險者，狡而工於爭。健者，強而力於爭。險而健，是以「訟」也。夫上剛下險，分兩體之上下，而以彼此言。「險而健」，則合兩體為一，而總言之也。若使險而不健，亦不能「訟」。健而不險，亦不生「訟」。唯險而又健，則內懷險惡，而多蓄智謀，外恃壯健，而不畏敲撲，「訟」之所以成也。此以卦德釋卦名義也。「健」字句絕，乃及於「訟」。或以健訟相連，誤矣。「剛來而得中」，指九二，九二蓋成卦之主爻也。自彼而此謂之來。「訟」乃「需」之倒體，「需」主爻在五，「訟」主爻在二。向為需之主，則剛處於五；今為訟之主，則剛來於二也。或謂「訟」為四陽卦，自「遁」來，而九三降為九二，非也。得中，謂居下體之中也。「訟不可成」，謂非吉德，得已則己，不得已而為之，亦不可極其終也。「中正」，指九五。訟唯中正而有理，則宜見中正之人，故曰「利見大人，尚中正也」。「淵」，指坎水。訟之時，人情乖違，深入險地，必遭陷溺，故曰「不利涉大川，入於淵」也。伊川程子曰：據卦才而言，更取成卦之由為義者，此是也。卦義不取成卦之由，則更不言所變之爻也。據卦辭，二乃善也，而爻中不見其善。蓋卦辭取其有孚得中而言，乃善也。爻則以自下訟上為義，所取不同也。</p><p>師，眾也。貞，正也。能以眾正，可以王矣。剛中而應，行險而順，以此毒天下，而民從之，吉，又何咎矣？</p><p>師者，眾也。周禮以五人為伍，五伍為兩，二十五人也；四兩為卒，百人也；五卒為旅，五百人也；五旅為師，二千五百人也。卦唯一陽，而有五陰之眾，故曰：「師，眾也。」「正」，謂兵出而有名也。書武成雲：「將有大正於商。」注云：「大正，以兵徵之。」蓋謂武王伐紂，以有道誅無道，是為大正也。孟子云：「徵之為言正也。」能役天下之眾，而以之討亂禁暴，弔民伐罪，然後謂之正。不正則兵出無名，人心不服，何以王天下？今興師動眾，而名正言順，可以王天下矣。故曰：「貞，正也。」能以眾正，可以王矣。</p><p>九二剛得中而無過，為上與六五柔中之君相應，故曰：「剛中而應。」行此危險之道，而上順天理，下順眾心，故曰：「行險而順。」夫兵者，不祥之器，用之則傷財害民，是毒天下也。蓋蠻夷寇賊，毒害於民，聖人不得已而伐之。用兵乃所以去其害，猶用瞑眩之毒藥以攻毒疾，疾既毒，則其用藥亦不容不毒也。如此而民皆從之，既吉而又無咎之者，以其剛中而應，行險而順也。故曰：「以此毒天下，而民從之，吉，又何咎矣？」不然，則雖欲無咎，且不可得，而況吉哉！涑水司馬公曰：「夫治眾不以剛，則慢而不振；用剛而不獲中，則暴而無親。上無應於君，下無應於民，則身危而功不成；所施不在於順，則眾怒而民不從。四者，非所以吉而無咎也。吉而無咎，則唯剛中而應，行險而順乎！」</p><p>比吉也。比，輔也，下順從也。原筮，元永貞，無咎，以剛中也。不寧方來，上下應也。後夫兇，其道窮也。</p><p>紫陽朱子以「比吉也」三字為衍文。郭京以「比吉」兩字為彖辭，但誤增「也」字。凡彖傳先舉彖辭，後以義結，彖辭下並無「也」字。姑蘇潘氏曰：「比輔」者，臣親其君也。「下順從」者，民親其君也。愚謂：比以九五為主，「輔」，謂六四不憚其勞而輔己也。「下順從」，謂在下三陰皆順而從己也。近有六四順而為之輔，下有三陰，順而無不從，此九五所以為比之吉也。「坤」，順也。初至四皆坤畫，有眾皆順從之象，上六不與焉。今但曰「下順從」而不及上，蓋斥上六在外也。「剛中」，謂九五剛而得中也。卦有內外二體，筮法先成者為內卦，後成者為外卦。故蒙以內卦為「初筮」，比以外卦為「原筮」。孔子釋蒙之「初筮」曰「以剛中也」。釋比之「原筮」亦曰「以剛中也」。蒙之「剛中」，乃九二，比之「剛中」，則九五是也。剛則所守者固，中則無過，為此所以「原筮，元永貞，無咎」也。厚齋馮氏曰：萃之與比，下體坤地則同，而上體水澤之象，亦不相遠。萃以九四一爻有分權之勢，故「元永貞」，於五言之。若比下無分其權者，故「元永貞」言之。於彖義各有在也。「上下應」，謂九五與初、二、三，上下之情相通也。眾方歸附之初，上下之情蓋猶未通，四居其間，不憚其勞，以下之意達於上，又以上之意達於下，然後上下之情通，故曰「不寧方來，上下應」也。上六處比之極，有不得其比之象，窮而無所歸，故曰「後夫兇，其道窮也」。周易集說卷十四，</p>',39)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
